"""Deliver exact current photo/folder links with a separate unresolved legacy review."""
import csv,hashlib,html,json,os,shutil
from pathlib import Path
from datetime import datetime,timezone
from urllib.parse import quote
H=Path(__file__).resolve().parent;BASE=H.parents[2];OUT=BASE/'outputs/fingerprint-numbered-master-refresh-2026-10-22';OUT.mkdir(exist_ok=True);(OUT/'images').mkdir(exist_ok=True)
read=lambda p:json.loads(Path(p).read_text());sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();e=lambda x:html.escape(str(x),quote=True)
inventory=read(H/'numbered-folder-inventory.json');cross=read(H/'legacy-crosswalk-review.json');overlay=read(H/'inputs/placement_overlay.before');assets=read(BASE/'components/reconciliation/photo-gap-completion-2026-10-22/current-assets.json')
def link(url,label):return '<a href="'+e(url)+'">'+e(label)+'</a>'
def local(p):return quote(os.path.relpath(p,OUT),safe='/')
def copy_original(fid):
 p=H/'native-originals'/(fid[3:]+'.jpeg');dest=OUT/'images'/p.name;shutil.copy2(p,dest);assert sha(dest)==sha(p);return local(dest)
cards=[]
for x in inventory:
 p=x['original_individual_photo'];im=copy_original(p['file_id']);gp=x['group_example'];cards.append('<article><h2>'+e(x['name'])+'</h2><a href="'+e(p['url'])+'"><img src="'+im+'" alt="'+e(x['name'])+'"></a><p>'+link(p['url'],'Individual original')+' · '+link(x['original_image_folder']['url'],'Containing photo folder')+' · '+link(x['component_folder']['url'],'Component folder')+'</p><p>'+link(gp['file']['url'],'Full group example')+' · '+link(gp['folder']['url'],'Containing group folder')+'</p><p>Individual: complete standalone photograph. Context: mounted-wall and full group references available.</p><p>'+e(x['legacy_alias_status'])+'. '+e(x['specification_status'])+'.</p><details><summary>Stable source IDs</summary><p>Original '+e(p['file_id'])+'<br>Photo folder '+e(x['original_image_folder']['file_id'])+'<br>Component folder '+e(x['component_folder']['file_id'])+'</p></details></article>')
legacy=[]
for x in cross:
 fid=x['historical_primary_file_id'];thumb=Path(assets[fid]['thumb']);dest=OUT/'images'/(fid[3:]+'-archived.jpg')
 if not dest.exists():shutil.copy2(thumb,dest)
 legacy.append('<article><h2>'+e(x['legacy_name'])+'</h2><img src="'+local(dest)+'" alt="Archived Left and Right pair"><p>Archived Left corresponds in curl direction to current2; archived Right to current3. The older panels have a different outline and finer, more numerous grooves. Same design/revision or separate design is unresolved.</p><p>'+link(x['candidate_original_image_url'],'Current White directional comparison')+' · '+link(x['candidate_white_folder_url'],'Current comparison folder')+' · '+link(local(x['archived_primary_local_path']),'Archived original (local)')+'</p><p>The White comparison does not establish a current Verdigris finish or a specification transfer.</p><details><summary>Preserved identities</summary><p>'+e(x['option_id'])+' · '+e(x['legacy_component_id'])+'<br>'+e(x['historical_primary_file_id'])+' · '+e(x['historical_primary_folder_id'])+'</p></details></article>')
photocards=[]
for p in overlay['photos']:
 photocards.append('<article><h2>'+e(p['finish']+' photograph '+str(p['image_number']))+'</h2><a href="'+e(p['file']['url'])+'"><img loading="lazy" src="'+local(p['source_local_path'])+'" alt="'+e(p['file']['name'])+'"></a><p>Left to right: '+e(' → '.join(map(str,p['left_to_right_component_numbers'])))+'. '+e(p['image_role'])+'.</p><p>'+link(p['file']['url'],'Dropbox original')+' · '+link(p['folder']['url'],'Containing folder')+'</p><details><summary>File and folder IDs</summary>'+e(p['file']['file_id'])+'<br>'+e(p['folder']['file_id'])+'</details></article>')
css='body{font:16px/1.5 Arial,sans-serif;background:#f5f6f3;color:#28362d;margin:0}main{max-width:1250px;margin:auto;padding:28px}h1{font-size:28px}h2{font-size:19px;color:#344e40}a{color:#245f7a}nav{padding:14px 0;border-bottom:1px solid #d7ded4}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:18px}article{background:white;padding:18px;border:1px solid #d7ded4;margin-top:16px}img{width:100%;height:290px;object-fit:contain;background:#eef1ec}details{font-size:12px;overflow-wrap:anywhere}.note{background:#e8eee5;padding:16px}'
nav='<nav>'+link('index.html','Six current numbered records')+' · '+link('photographs.html','All26 matched photographs')+' · '+link('legacy-alias-review.html','Legacy alias review')+'</nav>'
pages=[]
for name,title,body in [('index.html','Fingerprint current numbered folders','<p>Three numbered designs and two finish labels give six current folder-finish records. Each has a complete original JPEG, a containing folder and group examples.</p><p class="note">These six source records are tracked separately from the184 canonical catalogue options while the older Left/Right aliases are resolved. Current panel specifications have not been copied from the differently proportioned historical pair. The owner has been asked whether these are revised or separate designs.</p><div class="grid">'+''.join(cards)+'</div>'),('photographs.html','Fingerprint26 matched original photographs','<p>All26 photographs are in their seven Dropbox groups and retain their original bytes. The first four White images are detail/partial views; the remaining22 show full arrangements. The six standalone source JPEGs are listed on the current-records page.</p><div class="grid">'+''.join(photocards)+'</div>'),('legacy-alias-review.html','Fingerprint legacy Left/Right identity review','<p>Four historical finish options are preserved. Current2/3 share the curl directions of historical Left/Right, but an exact design-version link remains unresolved. The historical primary IDs did not resolve in the current metadata check and are absent from the current family subtree; this does not establish deletion elsewhere.</p><div class="grid">'+''.join(legacy)+'</div>')]:
 p=OUT/name;p.write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+'</title><style>'+css+'</style></head><body><main><h1>'+e(title)+'</h1>'+nav+'<p>'+link(overlay['family_folder']['url'],'Open Fingerprint in Dropbox')+'</p>'+body+'</main></body></html>');pages.append({'path':str(p),'sha256':sha(p)})
rows=[{'inventory_id':x['inventory_id'],'name':x['name'],'number':x['number'],'finish':x['finish'],'individual_image':x['original_individual_photo']['url'],'image_folder':x['original_image_folder']['url'],'component_folder':x['component_folder']['url'],'individual_file_id':x['original_individual_photo']['file_id'],'image_folder_id':x['original_image_folder']['file_id'],'component_folder_id':x['component_folder']['file_id'],'legacy_alias':x['legacy_alias_status'],'specification_scope':x['specification_status']}for x in inventory]
photos=[{'finish':p['finish'],'image_number':p['image_number'],'left_to_right_components':'/'.join(map(str,p['left_to_right_component_numbers'])),'image_url':p['file']['url'],'containing_folder':p['folder']['url'],'file_id':p['file']['file_id'],'folder_id':p['folder']['file_id'],'role':p['image_role'],'bytes':p['file']['bytes'],'source_sha256':p['source_sha256'],'native_content_hash':p['dropbox_content_hash']}for p in overlay['photos']]
csvs=[]
for name,data in [('Fingerprint_Current_Numbered_Records.csv',rows),('Fingerprint_All_26_Photo_Matches.csv',photos)]:
 p=OUT/name
 with p.open('w',encoding='utf-8-sig',newline='')as f:w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)
 csvs.append({'path':str(p),'sha256':sha(p),'rows':len(data)})
manifest={'status':'PASS_CURRENT_FP_LINK_REPORTS','recorded_utc':datetime.now(timezone.utc).isoformat(),'output_directory':str(OUT),'pages':pages,'csv_files':csvs,'image_files':[{'path':str(p),'sha256':sha(p)}for p in sorted((OUT/'images').iterdir())],'counts':{'current_folder_finish_records':6,'standalone_originals':6,'matched_originals':26,'full_arrangement_originals':22,'detail_partial_originals':4,'legacy_option_reviews':4,'canonical_options_added':0,'legacy_aliases_promoted':0}}
(H/'link-report-verification.json').write_text(json.dumps(manifest,indent=2)+'\n');print(json.dumps({'status':manifest['status'],'counts':manifest['counts']}))
